sys_script_include.script:
var RBH_ReportUtilAjax = Class.create();
RBH_ReportUtilAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    incidentSla: function(filter, table) {
        var unique = [];
        var latestbreach = {};
        var slaincident = new GlideRecord(table);
        slaincident.addEncodedQuery(filter);
        slaincident.orderByDesc('as_on');
        slaincident.query();

        while (slaincident.next()) {
            var taskid = slaincident.task.toString();
            var statusDate = slaincident.as_on;

            if (!latestbreach[taskid] || statusDate > latestbreach[taskid].date) {
                latestbreach[taskid] = {
                    sys_id: slaincident.sys_id.toString(),
                    date: statusDate
                };
            }
        }

        for (var slabreach in latestbreach) {
            unique.push(latestbreach[slabreach].sys_id);
        }

        return unique;
    },
    type: 'RBH_ReportUtilAjax'
});
